INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Samsung La Plata', 'Retail / Comercial', 'La Plata Buenos Aires', 2025, 'Ejecución de Obra: Samsung Experience Store – La Plata\nLa intervención en el local de Calle 8 N° 735, destinado al principal Samsung Experience Store de la ciudad de La Plata, representó un desafío integral de reconversión edilicia. El proyecto consistió en la transformación de un espacio con un uso previo totalmente distinto en un centro tecnológico de alto estándar.\n\nAlcance de las Tareas Técnicas\nEl proceso de obra se estructuró en dos fases críticas: la demolición total de la infraestructura preexistente y la posterior adecuación a los requerimientos de la marca.\n\nDemolición y Readecuación: Se procedió al desmonte integral de mampostería, cielorrasos y elementos estructurales no portantes para liberar la planta y permitir una nueva distribución funcional.\n\nFachada y Envolvente: Ejecución de una nueva fachada institucional, diseñada para cumplir con la identidad visual de Samsung y asegurar la permeabilidad visual hacia el salón de ventas.\n\nInstalaciones de Alta Complejidad: * Termomecánica: Montaje de sistemas de climatización de precisión.\n\nEléctrica e IT: Despliegue de una red de datos robusta y cableado estructurado para dar soporte a los dispositivos en exhibición (smartphones, tablets y wearables), cumpliendo con protocolos de conectividad de última generación.\n\nEquipamiento y Arquitectura Comercial: Montaje de mobiliario corporativo, accesorios de seguridad para equipos y señalética según los lineamientos globales de la marca.\n\nGestión y Estándares de Calidad\nLa ejecución se rigió por dos pilares fundamentales:\n\nManual de Marca: Cada detalle constructivo y de terminación fue supervisado bajo los estrictos estándares de calidad de Samsung, asegurando que la experiencia del usuario sea idéntica a la de cualquier tienda insignia (flagship) a nivel mundial.\n\nCumplimiento de Plazos: La obra se desarrolló bajo un cronograma de ruta crítica, lo que permitió coordinar los diversos gremios y asegurar la apertura del local en la fecha establecida por el cliente.', '["/images/obras/005_01.jpg","/images/obras/005_02.jpg","/images/obras/005_03.jpg","/images/obras/005_04.jpg","/images/obras/005_05.jpg","/images/obras/005_06.jpg","/images/obras/005_07.jpg","/images/obras/005_08.jpg","/images/obras/005_09.jpg"]', 1, 241.00, 'Samsung', 0, 1, 3, '2026-02-20 18:58:18', '2026-04-15 12:10:28');
