INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Banco Frances Sucursal Castro Barros', 'Bancos', 'Caballito Caba', 2026, 'Las intervenciones realizadas en sucursales del BBVA Argentina se ejecutan con la operación bancaria en pleno funcionamiento, sin interrupción del servicio al público. Este condicionante implica trabajar en un entorno de alta exigencia técnica y operativa, dado que la sucursal dispone de un sistema de cableado estructurado de gran complejidad, junto con instalaciones complementarias críticas (eléctricas, termomecánicas y de seguridad).\n\nDesde la etapa inicial del proyecto se desarrolló una planificación integral, materializada en un cronograma de obra detallado, donde se definieron fases, tiempos y secuencias de intervención. Este cronograma contempló especialmente la anticipación y coordinación de tareas sensibles, tales como desconexiones programadas, intervención sobre sistemas sísmicos, alarmas, pulsadores y demás dispositivos de seguridad, garantizando en todo momento la continuidad operativa de la sucursal.\n\nLa obra comprendió la intervención total del inmueble, incluyendo la demolición de los distintos sectores existentes, la redefinición funcional de los espacios y la adecuación de la imagen institucional conforme a manual corporativo vigente.\n\nDadas las restricciones operativas, las tareas se concentraron principalmente en días no hábiles (sábados, domingos y feriados), permitiendo ejecutar trabajos de alta interferencia en lapsos acotados. En muchos casos, el proceso implicó ciclos completos de desarme, demolición, ejecución y reinstalación en un plazo de 24 horas, asegurando que la sucursal retomara su actividad normal al día siguiente.\n\nLas principales tareas ejecutadas incluyeron:\n\nReemplazo y adecuación de tabiquería.\nIntervención y renovación de cielorrasos.\nReconfiguración de canalizaciones e instalaciones complementarias.\nMovimiento y adecuación de equipos ATM.\nEjecución de instalaciones termomecánicas.\nTrabajos de obra civil.\nAdecuación integral de instalaciones eléctricas.\n\nEste tipo de intervención requiere una coordinación precisa entre equipos, una logística ajustada y una planificación rigurosa, donde cada etapa se encuentra condicionada por la necesidad de mantener la operatividad continua del sistema bancario.', '["/images/obras/007_01.jpeg","/images/obras/007_02.jpg","/images/obras/007_03.jpg","/images/obras/007_04.jpg","/images/obras/007_05.jpg","/images/obras/007_06.jpg","/images/obras/007_07.jpg","/images/obras/007_08.jpg","/images/obras/007_09.jpg","/images/obras/007_10.jpg","/images/obras/007_11.jpg","/images/obras/007_12.jpg","/images/obras/007_13.jpg","/images/obras/007_14.jpg","/images/obras/007_15.jpg","/images/obras/007_16.jpg","/images/obras/007_17.jpg"]', 0, 490.00, 'BBVA', 0, 1, 0, '2026-04-15 14:45:47', '2026-04-15 17:13:28');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Banco Hipotecario - Directorio Edificio Central P6', 'Bancos', NULL, 2019, NULL, '["/images/obras/008_01.jpg","/images/obras/008_02.jpg","/images/obras/008_03.jpg","/images/obras/008_04.jpg","/images/obras/008_05.jpg"]', 4, 154.00, 'Banco Hipotecario', 0, 1, 24, '2026-02-20 19:00:18', '2026-04-15 17:47:46');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Mercedes Benz - Scrap', 'Industrial', NULL, 2023, 'Gestión de Infraestructura en Mercedes-Benz: Estándares Globales en Cada Detalle\nEn esta oportunidad se trabaja sobre un sector de scrap, realizando una cubierta parabolica de 30 x 15.\n\nOperar en el Centro Industrial Juan Manuel Fangio de Virrey del Pino representa el máximo nivel de exigencia en mantenimiento y obra civil. En este entorno, realizamos intervenciones integrales que van desde tareas preventivas y correctivas hasta obra nueva, abarcando bacheos, pavimentos, instalaciones térmicas y eléctricas, y terminaciones en seco (Durlock).\n\n¿Cuál es nuestro valor diferencial?\n\nPlanificación desde la Oficina Técnica: Cada tarea nace en nuestra oficina con planos y cronogramas precisos. Nada se deja al azar.\n\nCultura de Protocolo: Entendemos y aplicamos los estrictos protocolos de seguridad industrial. Nuestro personal (Arquitectos, Técnicos en SyH y Capataces) ingresa correctamente identificado y capacitado para entornos de alta criticidad.\n\nComunicación en Tiempo Real: Mantenemos un diálogo fluido con el cliente, reportando avances y encauzando desvíos de forma inmediata para garantizar que la información sea siempre transparente y oportuna.', '["/images/obras/009_01.jpg","/images/obras/009_02.jpg","/images/obras/009_03.jpg","/images/obras/009_04.jpg","/images/obras/009_05.jpg"]', 1, NULL, 'Mercedes Benz', 0, 1, 25, '2026-02-20 19:00:25', '2026-04-16 13:12:16');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Comedor Philips', 'Oficinas', NULL, 2018, NULL, '["/images/obras/010_01.jpg","/images/obras/010_02.jpg"]', 0, NULL, 'Philips', 0, 1, 38, '2026-02-20 19:01:57', '2026-02-20 19:01:57');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Droguerias del Sud Fachada', 'Industrial', 'San Cristonal', 2025, 'Entendemos que en una planta industrial, la obra no puede ser una carga. Por eso, basamos nuestra intervención en tres pilares que garantizan tranquilidad al cliente:\n\nIndependencia de Infraestructura: No utilizamos la red eléctrica del cliente. Operamos con herramientas inalámbricas de última generación y llegamos a la obra con nuestro propio tablero eléctrico normalizado, evitando sobrecargas en las instalaciones existentes.\n\nGestión Documental Transparente: Antes del primer movimiento, nuestro equipo presentó la memoria técnica, croquis y permisos de trabajo correspondientes. Trabajamos codo a codo con el departamento de Seguridad e Higiene del sitio para asegurar el cumplimiento del 100% de la normativa vigente.\n\nSupervisión de Triple Nivel: La obra no se delega, se gestiona. Contamos con presencia permanente de un Arquitecto, un Capataz y un Técnico en Seguridad e Higiene, velando por la calidad del acabado y el cumplimiento estricto del cronograma.\n\nFicha Técnica de la Obra\nSuperficie: 100 metros lineales de fachada técnica.\n\nTareas: Reparación de mampostería, pintura integral de fachada y carpinterías.\n\nEspecialidad: Pintura en altura sobre medianeras mediante medios de elevación ATS certificados por ingeniería.\n\nValor Agregado: Ejecución total con la planta en funcionamiento (Zero Downtime).', '["/images/obras/011_01.jpeg","/images/obras/011_02.jpeg","/images/obras/011_03.jpeg","/images/obras/011_04.jpeg","/images/obras/011_05.jpeg","/images/obras/011_06.jpeg","/images/obras/011_07.jpeg","/images/obras/011_08.jpeg","/images/obras/011_09.jpeg","/images/obras/011_10.jpeg","/images/obras/011_11.png"]', 10, 300.00, ' Droguerias del Sud srl', 0, 1, 0, '2026-04-15 14:03:32', '2026-04-16 11:58:23');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Ayassa Fombella', 'Oficinas', NULL, 2018, NULL, '["/images/obras/012_01.jpg","/images/obras/012_02.jpg","/images/obras/012_03.jpg","/images/obras/012_04.jpg"]', 2, 328.00, 'Ayassa', 0, 1, 21, '2026-02-20 18:59:49', '2026-04-15 17:33:32');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Mario Roberto Álvarez ex Banco italiano', 'Bancos', ' Av. Mitre y French, Avellaneda, Prov. de Buenos Aires.', 2026, 'Patrimonio y Modernidad: Intervención en el Ex Nuevo Banco Italiano\nUbicación: Av. Mitre y French, Avellaneda, Prov. de Buenos Aires.\nEdificación Original: 1960-1962.\nCliente: BBVA Argentina.\nIntervención: Renovación de imagen corporativa y adecuación funcional.\n\n1. El Desafío Operativo\nLa obra se sitúa en un edificio de alto valor histórico y gran volumen de flujo peatonal y bancario. El objetivo principal fue la ejecución total del cambio de imagen sin afectar la atención al público ni la seguridad de los activos financieros.\n\n2. Nuestra Metodología: "Cero Interrupción"\nEn Otegui Obras entendemos que la eficiencia de un banco no puede detenerse por una mejora edilicia. Nuestra estrategia se basó en:\n\nPlanificación Estratégica: Cada tarea se etapabilizó antes de ingresar al sitio. Aplicamos una logística de "Cero Improvisación", donde cada movimiento técnico está previsto en el cronograma de obra.\n\nJornadas de Alto Rendimiento: Para garantizar la continuidad operativa, el grueso de las tareas críticas se concentró en jornadas extendidas durante fines de semana y feriados, permitiendo que la sucursal inicie su actividad comercial cada lunes sin rastros de obra.\n\nPersonal Propio y Calificado: Contamos con equipos de trabajo directos, perfectamente identificados y con toda la documentación técnica y legal al día (ART, cláusulas de no repetición, ATS), cumpliendo con los estándares de seguridad industrial más exigentes.\n\n3. Resumen de Tareas Ejecutadas\nA partir de un presupuesto detallado y una ingeniería de costos precisa, las tareas incluyeron:\n\nTrabajos Preliminares: Replanteos técnicos, nivelación y armado de cierres provisorios de obra para aislar las áreas de trabajo.\n\nProtección de Activos: Cobertura integral del 100% de superficies de alfombras, mobiliario de oficina, ascensores y áreas de cajeros automáticos.\n\nRenovación de Imagen: Adecuación de revestimientos, cielorrasos y elementos de branding según el manual de marca vigente de BBVA.\n\nGestión de Residuos y Logística: Retiro constante de excedentes y limpieza técnica diaria para mantener el entorno de trabajo en condiciones óptimas.\n\n4. El Resultado\nGracias a la presencia de un Jefe de Obra full-time y una supervisión constante, logramos concluir la intervención en los plazos establecidos, demostrando que es posible realizar obras de gran envergadura en sitios críticos mediante la estrategia, el orden y el respeto por el tiempo del cliente.\n\nOtegui Obras: Transformamos espacios, preservamos la operatividad.', '["/images/obras/013_01.png","/images/obras/013_02.png","/images/obras/013_03.png","/images/obras/013_04.png","/images/obras/013_05.png","/images/obras/013_06.png","/images/obras/013_07.png","/images/obras/013_08.png","/images/obras/013_09.png","/images/obras/013_10.png","/images/obras/013_11.png","/images/obras/013_12.png","/images/obras/013_13.png","/images/obras/013_14.png","/images/obras/013_15.png","/images/obras/013_16.png","/images/obras/013_17.png","/images/obras/013_18.png","/images/obras/013_19.png","/images/obras/013_20.png","/images/obras/013_21.png","/images/obras/013_22.png","/images/obras/013_23.png"]', 22, 923.00, 'Frances', 0, 1, 0, '2026-04-20 14:16:28', '2026-04-20 14:51:17');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Ferri Real State - Cámara de Congelados', 'Industrial', NULL, 2022, NULL, '["/images/obras/014_01.jpg","/images/obras/014_02.jpg","/images/obras/014_03.jpg","/images/obras/014_04.jpg","/images/obras/014_05.jpg","/images/obras/014_06.jpg","/images/obras/014_07.jpg","/images/obras/014_08.jpg","/images/obras/014_09.jpg","/images/obras/014_10.jpg","/images/obras/014_11.jpg","/images/obras/014_12.jpg","/images/obras/014_13.jpg","/images/obras/014_14.jpeg","/images/obras/014_15.jpeg","/images/obras/014_16.jpeg"]', 14, NULL, 'Ferri Real State', 0, 1, 35, '2026-02-20 19:01:36', '2026-04-15 16:32:35');
