INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Cafetería Consejo de Ciencias Económicas ', 'Oficinas', 'Av. Córdoba 1532', 2022, 'Refuncionalización y Modernización de Oficinas: Intervención en el CPCE\nLa intervención en la sede del Consejo Profesional de Ciencias Económicas consistió en la transformación integral de espacios administrativos preexistentes. El proyecto se centró en la modernización de la infraestructura y la optimización funcional de las áreas de trabajo, bajo un esquema de ejecución de alta complejidad logística.\n\nGestión Logística y Coordinación de Obra\nDada la naturaleza de la institución, las tareas se desarrollaron en un entorno de trabajo activo. Esto requirió una planificación rigurosa para minimizar el impacto en las actividades diarias:\n\nCoordinación de Tareas: Se establecieron protocolos de comunicación constantes con la administración para el movimiento de personal y materiales.\n\nJornada Extendida: Para cumplir con el cronograma previsto sin afectar la operatividad del Consejo, se implementaron horarios extendidos y turnos especiales, permitiendo avanzar en las etapas más disruptivas fuera del horario comercial.\n\nAlcance de la Intervención Técnica\nEl proceso comprendió desde la demolición controlada hasta la renovación total de las terminaciones e instalaciones:\n\nDemolición y Remoción: Retiro de tabiquería, mobiliario fijo y elementos obsoletos para liberar la planta según el nuevo diseño arquitectónico.\n\nRevestimientos y Solados: Renovación de superficies verticales y cambio de pisos, seleccionando materiales de alta resistencia y estética contemporánea.\n\nCielorrasos y Pintura: Ejecución de nuevos cielorrasos (suspendidos/técnicos) y aplicación de esquemas de pintura profesional para potenciar la iluminación y el confort visual.\n\nInstalaciones Integrales: Actualización y refuncionalización de los sistemas:\n\nEléctricas: Cableado, tableros y terminales de datos.\n\nTermomecánicas: Adecuación de conductos y equipos de climatización.\n\nSanitarias: Ajuste de puntos de agua y desagües según la nueva distribución.', '["/images/obras/016_01.jpg","/images/obras/016_02.jpg","/images/obras/016_03.jpg","/images/obras/016_04.jpg","/images/obras/016_05.jpg","/images/obras/016_06.jpg"]', 1, 240.00, 'Consejo Prof. de Ciencias Económicas', 0, 1, 12, '2026-02-20 18:58:28', '2026-04-16 11:59:48');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Isadora Cabello', 'Retail / Comercial', 'Cabello 3621, C1425, Ciudad Autónoma de Buenos Aires', 2024, 'Refresh integral de local comercial de la marca Isadora, ejecutado bajo un plazo contractual exigente de 20 días. La intervención requirió una planificación detallada mediante cronograma de obra, ajustado dinámicamente durante la ejecución para garantizar el cumplimiento del plazo establecido.\n\nSe realizó el desmonte total de mobiliario existente y su posterior reposición conforme a los lineamientos del manual de marca. Asimismo, se ejecutó la renovación completa de instalaciones eléctricas y de IT, junto con la intervención en cielorrasos, solados, sistemas de climatización, desagües e instalaciones sanitarias, incluyendo provisión y montaje de cartelería corpórea.\n\nDada la alta densidad de elementos de exhibición propios del local, se fabricaron e instalaron múltiples componentes de manera individual, respetando estándares de diseño y calidad. La obra demandó jornadas de trabajo extendidas, incluyendo turnos nocturnos, fines de semana y feriados, permitiendo sostener el ritmo de avance sin desvíos en el plazo.\n\nEl resultado fue un espacio comercial completamente renovado, alineado a la identidad de marca y entregado en tiempo, pese a la complejidad operativa y la magnitud de tareas involucradas.', '["/images/obras/017_01.jpg","/images/obras/017_02.jpg","/images/obras/017_03.jpg","/images/obras/017_04.jpg","/images/obras/017_05.jpg","/images/obras/017_06.jpg","/images/obras/017_07.jpg","/images/obras/017_08.jpg","/images/obras/017_09.jpg"]', 6, 250.00, 'Blue Star Group', 0, 1, 4, '2026-02-20 18:56:30', '2026-04-14 18:07:55');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Sala de Lactancia - Av. Córdoba 1532', 'Oficinas', NULL, 2019, NULL, '["/images/obras/018_01.jpg","/images/obras/018_02.jpg","/images/obras/018_03.jpg","/images/obras/018_04.jpg","/images/obras/018_05.jpg"]', 3, 26.00, 'Consejo Prof. de Ciencias Económicas', 0, 1, 33, '2026-02-20 19:01:17', '2026-04-15 17:42:42');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Banco Francés - Sucursal 006 Constitución', 'Bancos', 'Bernardo de Irigoyen 1600', 2025, 'Transformación Integral con Operatividad Blindada\n\nLlevamos adelante la renovación total de una sucursal bancaria estratégica, logrando una adecuación completa a la nueva imagen corporativa sin interrumpir la atención al público. Desde la demolición de cielorrasos y solados hasta la intervención crítica en sectores de bóvedas, cajas y terminales ATM, cada paso fue coordinado para convivir con la actividad diaria de la entidad.\n\nLo que nos hace diferentes:\n\nSeguridad Institucional: Todo nuestro personal (operarios, ingenieros y arquitectos) cuenta con antecedentes certificados, garantizando idoneidad en áreas sensibles.\n\nTransparencia Radical: Nada se improvisa. Trabajamos con un cronograma estricto y una política de "información total": cada cambio o dato relevante es comunicado al cliente en tiempo real.\n\nPrecisión de Calendario: Gracias a una coordinación integral y seguimiento diario, entregamos la obra en el plazo pactado, con cero días de atraso.', '["/images/obras/019_01.jpg","/images/obras/019_02.png","/images/obras/019_03.png","/images/obras/019_04.png","/images/obras/019_05.png","/images/obras/019_06.png"]', 0, 200.00, 'Banco Francés', 0, 1, 0, '2026-02-20 18:56:19', '2026-04-16 12:21:27');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Mercado Libre - Sala de Descanso - CD Munro', 'Industrial', NULL, 2021, NULL, '["/images/obras/020_01.jpg","/images/obras/020_02.jpg","/images/obras/020_03.jpg","/images/obras/020_04.jpg"]', 1, 126.00, 'Mercado Libre', 0, 1, 26, '2026-02-20 19:00:31', '2026-04-15 14:11:33');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('ITBA Sueño', 'Institucional', 'Parque Patricios', 2023, 'Laboratorio de Sueño y Memoria - ITBA | "The Dream Machine"\nLa construcción del Laboratorio de Sueño y Memoria del ITBA representó un desafío de alta complejidad técnica y logística, al tratarse de un espacio destinado a la investigación de vanguardia en neurotecnología y realidad virtual. El objetivo central fue crear un entorno de aislamiento absoluto, donde las variables externas no interfieran con el monitoreo científico del descanso y la actividad onírica.\n\nGestión Logística en Entornos Educativos Activos\nDada la ubicación del proyecto dentro de la sede operativa del instituto, la ejecución se centró en la preservación de la actividad académica:\n\nPlanificación de Ruta Crítica: Se implementó un cronograma de trabajo estricto con horarios extendidos y nocturnos. Esta estrategia permitió avanzar en las etapas ruidosas sin afectar el normal funcionamiento de las aulas y oficinas circundantes.\n\nCoordinación de Suministros: La logística de materiales se realizó de manera atomizada para no obstruir los accesos compartidos con el alumnado y personal docente.\n\nIngeniería Acústica y Aislamiento de Alta Performance\nPara garantizar la viabilidad de las investigaciones, se ejecutó una solución de insonorización multicapa diseñada para alcanzar niveles críticos de silencio (habitaciones insonoras):\n\nTabiquería Técnica en Seco: Se montó un paquete acústico compuesto por triple placa de yeso de alta densidad (Durlock) en ambas caras, con un núcleo de lana de vidrio de alto espesor.\n\nBarreras de Densidad: Se integró el uso de barrera acústica Fonac (vinilo de alta densidad) en ambas caras del tabique, logrando una masa crítica capaz de frenar el paso de frecuencias bajas y medias.\n\nTratamiento de Superficies: La terminación interior se realizó con paneles fonoabsorbentes de primera línea, diseñados para eliminar la reverberación y garantizar una pureza sonora óptima para el uso de equipos de neurotecnología.\n\nControl de Vibraciones y Desacople Estructural\nUn factor determinante para el éxito de la obra fue el tratamiento de la transmisión por vía sólida:\n\nRuptura de Puentes Acústicos: Se evitó rigurosamente el contacto "chapa con chapa" en la estructura de los perfiles.\n\nMateriales Antivibratorios: Todos los puntos de anclaje y encuentros estructurales fueron tratados con materiales resilientes y selladores específicos. Este "desacople" asegura que las vibraciones del edificio (causadas por tráfico, aire acondicionado o tránsito de personas) no ingresen a las cámaras de estudio.\n\nValor Agregado para Proyectos Científicos e Industriales\nEste proyecto demuestra nuestra capacidad para ejecutar obras de especialidad técnica donde el estándar constructivo convencional no es suficiente. La combinación de precisión en la ejecución de obra en seco, conocimiento de materiales de aislamiento acústico y una gestión logística invisible, nos permite entregar espacios que cumplen con las normativas más exigentes de la industria científica y tecnológica.', '["/images/obras/021_01.jpg","/images/obras/021_02.jpg","/images/obras/021_03.jpg","/images/obras/021_04.jpg","/images/obras/021_05.jpg","/images/obras/021_06.jpg","/images/obras/021_07.jpg","/images/obras/021_08.jpg"]', 3, NULL, 'ITBA', 0, 1, 10, '2026-02-20 18:58:06', '2026-04-15 12:37:25');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Pfizer - Depósito Ottaviano', 'Industrial', NULL, 2019, NULL, '["/images/obras/022_01.jpg","/images/obras/022_02.jpg","/images/obras/022_03.jpg","/images/obras/022_04.jpg","/images/obras/022_05.jpg","/images/obras/022_06.jpg"]', 2, 175.00, 'Pfizer', 0, 1, 41, '2026-02-20 19:02:19', '2026-04-15 16:59:40');
