INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Mercedes Benz Parada de Planta', 'Industrial', 'Virrey del Pino', 2025, 'Mantenimiento y Estabilidad Funcional: Centro Industrial Juan Manuel Fangio\n\nEn el Centro Industrial Juan Manuel Fangio (Virrey del Pino), núcleo productivo con más de 74 años de historia en Argentina, ejecutamos un programa integral de intervenciones técnicas en las Plantas 1 y 2. El objetivo central fue garantizar la operatividad continua y la seguridad estructural en un entorno de máxima exigencia.\n\nLa obra abarcó la renovación de solados y pavimentos mediante tecnologías de alta resistencia, como sistemas de epoxi y poliuretano, además de demarcaciones viales internas y la reparación técnica de cubiertas. Complementariamente, se realizó la puesta en valor de áreas de servicios, incluyendo vestuarios y sanitarios.\n\nLa complejidad de una planta automotriz en funcionamiento requirió una logística de precisión: trabajamos bajo estrictos protocolos industriales y en horarios rotativos para no interferir con el ritmo de producción. El control total de la obra estuvo garantizado por la presencia permanente de un equipo interdisciplinario (Arquitecto, Jefe de Obra, Capataz y Técnico en Seguridad e Higiene), asegurando calidad y cumplimiento en cada etapa.', '["/images/obras/024_01.png","/images/obras/024_02.jpg","/images/obras/024_03.jpg","/images/obras/024_04.jpg","/images/obras/024_05.jpg","/images/obras/024_06.jpg","/images/obras/024_07.jpg","/images/obras/024_08.jpg","/images/obras/024_09.jpg","/images/obras/024_10.jpg","/images/obras/024_11.jpg","/images/obras/024_12.jpg","/images/obras/024_13.jpg","/images/obras/024_14.jpg","/images/obras/024_15.jpg","/images/obras/024_16.jpg","/images/obras/024_17.jpg","/images/obras/024_18.jpg","/images/obras/024_19.jpg","/images/obras/024_20.jpg"]', 0, NULL, 'Mercedes Benz', 0, 1, 0, '2026-04-14 18:42:44', '2026-04-14 18:54:22');
