INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Rouge Unicenter', 'Retail / Comercial', 'Unicenter Shopping', 2024, 'Se llevó a cabo la transformación total de un espacio comercial en el Shopping Unicenter para la firma Perfumes Rouge. El proyecto incluyó la demolición completa de solados, tabiquerías y fachada, junto con una intervención integral de las instalaciones para adecuarlas a los requerimientos del nuevo uso. Bajo un estricto cumplimiento del manual de marca y una planificación logística ajustada a jornadas nocturnas, la obra se entregó en los plazos establecidos, garantizando la operatividad del centro comercial y la excelencia en las terminaciones.', '["/images/obras/027_01.jpg","/images/obras/027_02.jpg","/images/obras/027_03.jpg","/images/obras/027_04.jpeg","/images/obras/027_05.jpg","/images/obras/027_06.jpeg","/images/obras/027_07.jpg","/images/obras/027_08.jpg"]', 3, 180.00, NULL, 1, 1, 2, '2026-04-14 14:08:30', '2026-04-14 16:12:07');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('CCU 2023', 'Oficinas', 'Edison 2669, Piso 1, Martínez (1640), San Isidro', 2023, 'Llevamos a cabo la transformación completa de la planta en el edificio Riverside (CABA), rediseñando el espacio para las nuevas oficinas de CCU. El proyecto comenzó con una etapa crítica de demolición técnica que abarcó 300 m² de solados, tabiquería vidriada y cielorrasos modulares, además del retiro integral de instalaciones sanitarias preexistentes.\n\nLa nueva configuración se centró en la optimización acústica y funcional, utilizando tabiquería de alta prestación (Durlock con barrera acústica Fonac) y sistemas de cielorrasos suspendidos con terminaciones de precisión. Bajo una supervisión constante de Seguridad e Higiene, garantizamos una ejecución limpia, segura y alineada con los estándares de calidad que un entorno corporativo de primer nivel exige.', '["/images/obras/028_01.jpg","/images/obras/028_02.jpg","/images/obras/028_03.jpg","/images/obras/028_04.jpg","/images/obras/028_05.jpg","/images/obras/028_06.jpg"]', 5, 900.00, 'CCU Argentina', 0, 1, 6, '2026-02-20 18:57:24', '2026-04-14 18:05:49');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Equaphone', 'Oficinas', 'Espinosa 2539, C1416CFC, Ciudad Autónoma de Buenos Aires.', 2025, 'Adecuación integral de galpón existente para su transformación en oficinas corporativas y showroom orientado a experiencias de sonido multimedia. La intervención implicó una planificación técnica precisa para reconvertir un espacio industrial en un entorno funcional, acústicamente controlado y alineado a los requerimientos del cliente.\n\nSe ejecutaron tabiquerías, carpinterías y sistemas de acondicionamiento acústico mediante la construcción de paredes insonorizadas, junto con cielorrasos, solados y revestimientos. Asimismo, se realizó la provisión e instalación de mobiliario fijo, la construcción de dos núcleos sanitarios y un office, además de la ejecución de instalaciones complementarias.\n\nEl resultado fue un espacio corporativo y experiencial de alta prestación, diseñado para optimizar el desempeño acústico y acompañar el uso técnico y comercial del cliente.\n', '["/images/obras/029_01.jpg","/images/obras/029_02.jpg","/images/obras/029_03.jpg","/images/obras/029_04.jpg","/images/obras/029_05.jpg","/images/obras/029_06.jpg","/images/obras/029_07.webp","/images/obras/029_08.jpeg"]', 4, 230.00, 'Equaphone', 0, 1, 9, '2026-02-20 18:57:55', '2026-04-14 15:57:12');
