INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Deposito Blue Star Group', 'Industrial', 'Rio Limay 1630', 2024, 'Refuncionalización Logística Integral: Compromiso y Precisión Técnica\nTransformamos una nave industrial existente en un centro de depósitos de alta eficiencia para la firma Bluestar Group. Este proyecto es el reflejo de nuestra metodología de trabajo: una combinación de rigor técnico, seguridad absoluta y cumplimiento estricto de los plazos.\n\nSeguridad y Responsabilidad en Tareas Críticas\nAsumimos el desafío de la remoción total de la cubierta de asbesto, un proceso de alta complejidad que ejecutamos bajo estrictos protocolos de Trabajo en Altura y ATS.\n\nCultura Preventiva: La obra contó con supervisión permanente de especialistas en Seguridad e Higiene, integrando charlas de capacitación técnica y preventiva al inicio de cada jornada. El resultado: una ejecución con cero incidentes.\n\nIngeniería y Control de Calidad\nFrente a la complejidad de un suelo con presencia de agua, no improvisamos.\n\nSoluciones de Fondo: Trabajamos junto a ingenieros calculistas y realizamos ensayos de capacidad portante para diseñar un paquete de pisos en hormigón armado de alta resistencia, garantizando la durabilidad del activo para el cliente.\n\nRenovación Estructural: Ejecutamos una nueva cubierta parabólica, fachada integral y sistemas de desagües e instalaciones diseñados para el uso intensivo.\n\nGestión de Tiempos y Resultados\nEntendemos que el tiempo es un recurso crítico para nuestros clientes. Gracias a una planificación rigurosa y un control de obra constante, no solo cumplimos con el calendario pactado, sino que logramos la entrega final 5 días antes de la fecha establecida.\n\nEn cada proyecto, nuestra prioridad es el control total de la obra y la tranquilidad de quien confía en nosotros.', '["/images/obras/042_01.jpg","/images/obras/042_02.jpg","/images/obras/042_03.jpg","/images/obras/042_04.jpg","/images/obras/042_05.jpg","/images/obras/042_06.jpg","/images/obras/042_07.jpg","/images/obras/042_08.jpg","/images/obras/042_09.jpeg","/images/obras/042_10.jpeg"]', 9, 290.00, NULL, 0, 1, 14, '2026-02-20 18:57:33', '2026-04-14 16:11:25');
