INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Banco Galicia Suc. 697', 'Retail / Comercial', 'Juan Domingo Peron 1235 San Miguel', 2026, 'Ficha Técnica: Logística de Seguridad y Obra Civil – Banco Galicia Sucursal San Miguel\nIntervención Crítica: Recambio de Puertas de Tesoro y Reacondicionamiento de Áreas de Alta Seguridad\nUbicación: San Miguel, Prov. de Buenos Aires.\nCliente: Banco Galicia.\nEspecialidad: Logística pesada, movimiento de caudales y arquitectura comercial.\n\n1. El Desafío: Precisión en Operaciones de Alta Seguridad\nLa sustitución de puertas de tesoro representa uno de los desafíos logísticos y civiles más complejos en el ámbito bancario. Requiere la coordinación exacta entre la seguridad bancaria, el transporte de blindados y la ejecución de obra civil para garantizar que los activos de la entidad nunca queden vulnerables.\n\n2. Metodología de Ejecución: El Estratega en Obra\nEn Otegui Obras, abordamos esta intervención bajo una premisa de orden absoluto, evitando cualquier margen de improvisación:\n\nLogística de Acceso y Señalización: Se procedió a la delimitación y señalización del acceso peatonal exclusivo para el ingreso de las nuevas unidades de seguridad, garantizando la integridad de los transeúntes y la fluidez del operativo.\n\nDespeje de Obstáculos y Desarme Técnico: Antes del movimiento de carga, nuestro equipo realizó el desarme estratégico de mobiliario, mamparas, tabiques y elementos arquitectónicos que obstruían el radio de giro y el paso de las puertas.\n\nSustitución de Componentes de Seguridad: Coordinamos el retiro de las unidades obsoletas y la colocación de las nuevas puertas, compuestas por una coraza maciza y enteriza en Acero SAE 1010/1020, asegurando su correcto anclaje y nivelación según los protocolos de seguridad del banco.\n\n3. Reacondicionamiento y Entrega "Llave en Mano"\nNuestra responsabilidad no termina con la instalación técnica. Una vez asegurado el tesoro, procedemos a la restauración del entorno:\n\nReparación Civil: Se reconstruyen y reparan los tabiques y superficies que pudieran haber resultado dañados o manchados durante el movimiento de los componentes de acero pesado.\n\nReordenamiento Funcional: El mobiliario y las mamparas se reensamblan en su posición original, devolviendo a la sucursal su capacidad operativa completa.\n\nLimpieza Fina: La obra se entrega tras un proceso de limpieza profunda, permitiendo que el personal bancario retome sus tareas en un ambiente impecable y sin rastros de la intervención civil.\n\n4. Valor Agregado: Compromiso Otegui Obras\nEsta obra es un ejemplo de nuestra capacidad para gestionar personal propio perfectamente identificado y con documentación al día, trabajando bajo una planificación rígida que respeta la operatividad del banco. La combinación de fuerza civil y precisión logística nos convierte en el socio estratégico ideal para intervenciones en áreas críticas de seguridad.\n\nOtegui Obras: Soluciones técnicas para entornos de alta exigencia.', '["/images/obras/045_01.jpg","/images/obras/045_02.jpg","/images/obras/045_03.jpg","/images/obras/045_04.jpg","/images/obras/045_05.jpg","/images/obras/045_06.jpg"]', 0, 290.00, 'Galicia', 0, 1, 0, '2026-04-20 15:20:58', NULL);
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Colegio Publico de abogados caba', 'Oficinas', 'Corrientes 1441', 2022, 'En esta Oportunidad se nos encomienda, la refuncionalizacin de las oficinas en primer piso en el colegio publico de abogados en caba, las tareas se realizan durante el edificio operando lo que requirio coordinación a fin de no entorpecer el normal funcionamiento del sitio, entre sus tareas se encuentran tabiquerias vidriadras, colocacion de carpinterias, canalizacion de corriente normal y debiles. colocacion de alfombra, cielo rasos, muros y pintura. ', '["/images/obras/046_01.jpg","/images/obras/046_02.jpg","/images/obras/046_03.jpg","/images/obras/046_04.jpeg","/images/obras/046_05.jpg","/images/obras/046_06.jpg","/images/obras/046_07.jpg","/images/obras/046_08.jpg","/images/obras/046_09.jpg","/images/obras/046_10.jpg","/images/obras/046_11.jpg"]', 3, 103.00, 'Colegio de abogados', 0, 1, 36, '2026-02-20 19:01:40', '2026-04-15 18:33:05');
INSERT INTO obras (nombre, categoria, ubicacion, anno, descripcion, imagenes, imagen_portada, metros_cuadrados, cliente, destacada, visible, orden, fecha_creacion, fecha_modificacion) VALUES ('Puppis - Balbín', 'Retail / Comercial', 'Av. Dr. Ricardo Balbín 3650, CABA', 2024, 'Se trata de la ejecución integral de un local comercial para la firma Puppis, franquicia especializada en insumos para mascotas, desarrollado sobre una superficie de 324 m². El principal condicionante del proyecto fue el plazo: una obra con un máximo de 20 días, lo que exigió una planificación precisa, control riguroso y una ejecución sin desvíos.\n\nAntes del inicio, se realizó una planificación completa de la obra, definiendo secuencias, solapes de tareas y provisión anticipada de materiales. Esto permitió reducir tiempos muertos y asegurar continuidad operativa desde el primer día. La estrategia de ejecución se apoyó en jornadas ampliadas y en la conformación de equipos mixtos, combinando personal calificado con supervisión constante en campo.\n\nLa obra fue conducida por un jefe de obra y un capataz, quienes garantizaron el cumplimiento del cronograma, la calidad de ejecución y la correcta interpretación del manual de marca, un punto crítico en este tipo de franquicias donde la estandarización es clave para la identidad comercial.\n\nEn términos técnicos, se intervino de manera integral sobre el espacio existente:\n\nReadecuación de solados según requerimientos de uso intensivo comercial.\nEjecución de cielorrasos técnicos y arquitectónicos.\nConstrucción de tabiquerías en sistema en seco (Durlock), optimizando tiempos y precisión.\nReacondicionamiento completo de servicios: baño y área de apoyo (cocina).\nAdaptación de la instalación eléctrica al nuevo uso, considerando carga, distribución y normativa vigente.\nEjecución de instalaciones sanitarias, incluyendo plomería, desagües pluviales y cloacales primarios.\n\nEl resultado fue una obra finalizada en 18 días, es decir, por debajo del plazo máximo establecido, sin comprometer calidad ni terminaciones.', '["/images/obras/047_01.jpg","/images/obras/047_02.jpg","/images/obras/047_03.jpg","/images/obras/047_04.jpg","/images/obras/047_05.jpg","/images/obras/047_06.jpg","/images/obras/047_07.jpg","/images/obras/047_08.jpg","/images/obras/047_09.jpg"]', 3, 324.00, 'Puppis', 0, 1, 4, '2026-02-20 18:56:57', '2026-04-14 17:36:20');
